func (t Event) ValueByDiscriminator() (interface{}, error) {
	discriminator, err := t.Discriminator()
	if err != nil {
		return nil, err
	}
	switch discriminator {
	case "claim":
		return t.AsClaimEvent()
	case "decision":
		return t.AsDecisionEvent()
	case "demand":
		return t.AsDemandEvent()
	case "host":
		return t.AsHostEvent()
	case "resync":
		return t.AsResyncEvent()
	case "worker":
		return t.AsWorkerEvent()
	default:
		return nil, errors.New("unknown discriminator value: " + discriminator)
	}
}

